// updateSchemas regenerates schemas/v1 from the Go types. Schemas are not
// regenerated by task test:update: go test ./... -update fails in packages
// whose tests do not define -update.
var updateSchemas = flag.Bool("update", false, "regenerate schemas/v1 from Go types")

const schemaStringType = "string"

// TestGenerateSchemas reflects every Roots entry into schemas/v1 and fails
// on drift. Run task generate to refresh.
func TestGenerateSchemas(t *testing.T) {
	roots := Roots()
	generated := make(map[string][]byte, len(roots))
	for _, root := range roots {
		generated[root.Name+".schema.json"] = generateSchema(t, root)
	}
	dir := "../../schemas/v1"
	if *updateSchemas {
		require.NoError(t, os.MkdirAll(dir, 0o700))
		for name, content := range generated {
			require.NoError(t, os.WriteFile(filepath.Join(dir, name), content, 0o600))
		}
		entries, err := os.ReadDir(dir)
		require.NoError(t, err)
		for _, entry := range entries {
			if _, ok := generated[entry.Name()]; !ok {
				require.NoError(t, os.Remove(filepath.Join(dir, entry.Name())))
			}
		}
		return
	}
	for name, want := range generated {
		got, err := os.ReadFile(filepath.Join(dir, name))
		require.NoError(t, err, "missing schema file")
		require.Equal(t, string(want), string(got), "schemas/v1 is stale: run task generate")
	}
}

// generateSchemaMu serializes schema generation across parallel subtests.
// clearDescriptions mutates shared reflector subschemas in place, so
// concurrent generateSchema calls race even for unrelated roots.
var generateSchemaMu sync.Mutex

func generateSchema(t *testing.T, root Root) []byte {
	t.Helper()
	generateSchemaMu.Lock()
	defer generateSchemaMu.Unlock()
	mapper := versionedSchemaTypeMapper(root.Since)
	reflector := &jsonschema.Reflector{
		ExpandedStruct: true,
		Mapper:         mapper,
		Namer: func(valueType reflect.Type) string {
			if valueType == reflect.TypeOf(legacyGlimmerCallRecord{}) {
				return "GlimmerCallRecord"
			}
			return ""
		},
	}
	// Apply root overrides directly: Reflect would replace their nested $defs.
	schema := mapper(reflect.TypeOf(root.New()).Elem())
	if schema == nil {
		schema = reflector.Reflect(root.New())
	}
	schema.Version = SchemaDialect
	schema.ID = jsonschema.ID(SchemaIDBase + root.Name + ".schema.json")
	schema.Title = root.Title
	if schema.Title == "" {
		schema.Title = reflect.TypeOf(root.New()).Elem().Name()
	}
	clearDescriptions(schema)
	out, err := json.MarshalIndent(schema, "", "  ")
	require.NoError(t, err)
	return append(out, '\n')
}

// versionedExcept is since's versioned mapper for every type but root, so a
// legacy root can be reflected with its milestone's nested types and then
// trimmed.
func versionedExcept(since string, root reflect.Type) func(reflect.Type) *jsonschema.Schema {
	return func(valueType reflect.Type) *jsonschema.Schema {
		if valueType == root {
			return nil
		}
		return versionedSchemaTypeMapper(since)(valueType)
	}
}

// versionedSchemaTypeMapper keeps previously published envelope schemas byte
// for byte frozen while the runtime accepts additive methods and ops.
func versionedSchemaTypeMapper(since string) func(reflect.Type) *jsonschema.Schema {
	return func(valueType reflect.Type) *jsonschema.Schema {
		if since == MilestoneV17 && valueType == reflect.TypeOf(IncidentListResult{}) {
			// Source-read evidence belongs to v1.8, not the published v1.7 root.
			legacy := (&jsonschema.Reflector{ExpandedStruct: true, Mapper: schemaTypeMapper}).Reflect(&IncidentListResult{})
			item := legacy.Definitions["IncidentListItem"]
			item.Properties.Delete("source_read_at")
			item.Required = slices.DeleteFunc(item.Required, func(name string) bool {
				return name == "source_read_at"
			})
			return legacy
		}
		// tmux_attach is a runtime extension for already-running agents. The
		// published v1 roots stay byte-for-byte frozen until a versioned root
		// advertises the new transport.
		if since != MilestoneV19 && since != MilestoneV110 && since != MilestoneV111 && since != MilestoneV112 && since != MilestoneV113 && valueType == reflect.TypeOf(GuardName("")) {
			// screen_unchanged and detector_fallback belong to contracts-v1.9,
			// not the published roots: frozen guard lists stay untouched.
			return enumSchemaExcept(GuardName("").EnumValues(),
				string(GuardNameScreenUnchanged), string(GuardNameDetectorFallback))
		}
		if since != MilestoneV112 && since != MilestoneV113 && valueType == reflect.TypeOf(AgentListResult{}) {
			// Pane-lock status and the detector wait belong to
			// contracts-v1.12: the published agent list stays frozen.
			legacy := (&jsonschema.Reflector{ExpandedStruct: true, Mapper: versionedExcept(since, valueType)}).Reflect(&AgentListResult{})
			item := legacy.Definitions["AgentListItem"]
			item.Properties.Delete("pane_lock")
			item.Properties.Delete("waiting")
			delete(legacy.Definitions, "AgentPaneLockStatus")
			return legacy
		}
		if since != MilestoneV113 && valueType == reflect.TypeOf(DeliveryDecisionListResult{}) {
			// The decision's source, model and call belong to
			// contracts-v1.13; its policy and hold to contracts-v1.12.
			legacy := (&jsonschema.Reflector{ExpandedStruct: true, Mapper: versionedExcept(since, valueType)}).Reflect(&DeliveryDecisionListResult{})
			item := legacy.Definitions["DeliveryDecisionListItem"]
			item.Properties.Delete("source")
			item.Properties.Delete("decision_model")
			item.Properties.Delete("glimmer_call_id")
			delete(legacy.Definitions, "DeliveryDecisionSource")
			if since != MilestoneV112 {
				item.Properties.Delete("policy_version")
				item.Properties.Delete("hold")
			}
			return legacy
		}
		if since != MilestoneV112 && since != MilestoneV113 && valueType == reflect.TypeOf(StateObservationReport{}) {
			// The detector verdict belongs to contracts-v1.12 and the
			// unknown-cursor mark to contracts-v1.9: the published v1.3
			// report keeps its frozen shape with row and col only.
			legacy := (&jsonschema.Reflector{ExpandedStruct: true, Mapper: schemaTypeMapper}).Reflect(&StateObservationReport{})
			legacy.Properties.Delete("detector")
			delete(legacy.Definitions, "StateObservationDetector")
			if since != MilestoneV19 && since != MilestoneV110 && since != MilestoneV111 && since != MilestoneV112 && since != MilestoneV113 {
				if cursor, ok := legacy.Definitions["StateObservationCursor"]; ok && cursor != nil {
					cursor.Properties.Delete("known")
				}
			}
			return legacy
		}
		if since != MilestoneV110 && since != MilestoneV111 && since != MilestoneV112 && since != MilestoneV113 && valueType == reflect.TypeOf(ModelGateStatus("")) {
			// Operator overrides belong to contracts-v1.10. Published model
			// roots retain the original two-value enum byte for byte.
			return enumSchemaExcept(ModelGateStatus("").EnumValues(), string(ModelGateStatusOverride))
		}
		if valueType == reflect.TypeOf(InputGuardProvider("")) {
			return enumSchemaExcept(InputGuardProvider("").EnumValues(), string(InputGuardProviderTmuxAttach))
		}
		if valueType == reflect.TypeOf(CaptureMode("")) {
			return enumSchemaExcept(CaptureMode("").EnumValues(), string(CaptureModeTmuxAttach))
		}
		if valueType == reflect.TypeOf(ErrorCode("")) {
			excluded := []string{
				string(ErrorCodeArtifactNotFound), string(ErrorCodeNotSender),
				string(ErrorCodeChannelNotAllowed), string(ErrorCodeReservationConflict),
				string(ErrorCodeChunkOutOfRange), string(ErrorCodeChunkSizeInvalid),
				string(ErrorCodeChunkDigestMismatch), string(ErrorCodeUploadIncomplete),
				string(ErrorCodeCiphertextDigestMismatch),
			}
			if since != MilestoneV111 && since != MilestoneV112 && since != MilestoneV113 {
				excluded = append(excluded,
					string(ErrorCodeReminderTombstoned),
					string(ErrorCodeReminderWriteBusy),
				)
			}
			return enumSchemaExcept(ErrorCode("").EnumValues(), excluded...)
		}
		if valueType == reflect.TypeOf(ModelProfileSource("")) && since != MilestoneV15 && since != MilestoneV16 && since != MilestoneV17 && since != MilestoneV18 && since != MilestoneV19 && since != MilestoneV110 && since != MilestoneV111 && since != MilestoneV112 && since != MilestoneV113 {
			return enumSchemaExcept(ModelProfileSource("").EnumValues(), string(ModelProfileSourceControlState))
		}
		if valueType == reflect.TypeOf(ControlMethod("")) {
			switch since {
			case MilestoneV110, MilestoneV111, MilestoneV112, MilestoneV113:
				return schemaTypeMapper(valueType)
			case MilestoneV19:
				return enumSchemaExcept(ControlMethod("").EnumValues(), string(ControlMethodModelActivateOverride))
			case MilestoneV17, MilestoneV18:
				return enumSchemaExcept(ControlMethod("").EnumValues(), append(
					paneControlMethodNames(), string(ControlMethodModelActivateOverride))...)
			case MilestoneV16:
				return enumSchemaExcept(ControlMethod("").EnumValues(), append([]string{
					string(ControlMethodIncidentList), string(ControlMethodBridgeRetireRecipient), string(ControlMethodModelActivateOverride),
				}, paneControlMethodNames()...)...)
			case MilestoneV15:
				return enumSchemaExcept(ControlMethod("").EnumValues(), append([]string{
					string(ControlMethodDeliveryDecisionList), string(ControlMethodIncidentList), string(ControlMethodBridgeRetireRecipient), string(ControlMethodModelActivateOverride),
				}, paneControlMethodNames()...)...)
			case MilestoneV14:
				return enumSchemaExcept(ControlMethod("").EnumValues(), append([]string{
					string(ControlMethodModelRegister), string(ControlMethodModelRegisterPipeline), string(ControlMethodModelActivate),
					string(ControlMethodModelActivateOverride), string(ControlMethodModelRollback), string(ControlMethodDeliveryDecisionList), string(ControlMethodIncidentList), string(ControlMethodBridgeRetireRecipient),
				}, paneControlMethodNames()...)...)
			case MilestoneV12, MilestoneV13:
				return enumSchemaExcept(ControlMethod("").EnumValues(), append([]string{
					string(ControlMethodDeliveryList), string(ControlMethodModelRegister), string(ControlMethodModelRegisterPipeline),
					string(ControlMethodModelActivate), string(ControlMethodModelActivateOverride), string(ControlMethodModelRollback),
					string(ControlMethodDeliveryDecisionList), string(ControlMethodIncidentList), string(ControlMethodBridgeRetireRecipient),
				}, paneControlMethodNames()...)...)
			default:
				return enumSchemaExcept(ControlMethod("").EnumValues(), append([]string{
					string(ControlMethodNotificationList), string(ControlMethodDeliveryList),
					string(ControlMethodModelRegister), string(ControlMethodModelRegisterPipeline), string(ControlMethodModelActivate),
					string(ControlMethodModelActivateOverride), string(ControlMethodModelRollback), string(ControlMethodDeliveryDecisionList), string(ControlMethodIncidentList), string(ControlMethodBridgeRetireRecipient),
				}, paneControlMethodNames()...)...)
			}
		}
		if valueType == reflect.TypeOf(AgentOp("")) {
			switch since {
			case MilestoneV14, MilestoneV15, MilestoneV16, MilestoneV17, MilestoneV18, MilestoneV19, MilestoneV110, MilestoneV111, MilestoneV112, MilestoneV113:
				return schemaTypeMapper(valueType)
			case MilestoneV13:
				return enumSchemaExcept(AgentOp("").EnumValues(),
					string(AgentOpAnnounceSupport), string(AgentOpEmitEventResult))
			default:
				return enumSchemaExcept(AgentOp("").EnumValues(),
					string(AgentOpReportStateObservation), string(AgentOpAnnounceSupport),
					string(AgentOpEmitEventResult))
			}
		}
		return schemaTypeMapper(valueType)
	}
}

func paneControlMethodNames() []string {
	return []string{
		string(ControlMethodPaneProvision),
		string(ControlMethodPaneTake),
		string(ControlMethodPaneReturn),
		string(ControlMethodPaneReconcile),
		string(ControlMethodPaneRepair),
	}
}

func enumSchemaExcept(values []string, excluded ...string) *jsonschema.Schema {
	enum := make([]any, 0, len(values)-len(excluded))
	for _, value := range values {
		keep := true
		for _, blocked := range excluded {
			if value == blocked {
				keep = false
				break
			}
		}
		if keep {
			enum = append(enum, value)
		}
	}
	return &jsonschema.Schema{Type: schemaStringType, Enum: enum}
}

// schemaTypeMapper maps contract scalar types to their schema: string enums
// in table order, RE2 patterns, raw JSON shapes and the version vector.
func schemaTypeMapper(t reflect.Type) *jsonschema.Schema {
	if t == reflect.TypeOf(BridgeReminderTombstoneMarker(false)) {
		return &jsonschema.Schema{Type: "boolean", Const: true}
	}
	if t.Kind() == reflect.String {
		zero := reflect.Zero(t).Interface()
		if e, ok := zero.(interface{ EnumValues() []string }); ok {
			values := e.EnumValues()
			enum := make([]any, len(values))
			for i, v := range values {
				enum[i] = v
			}
			return &jsonschema.Schema{Type: schemaStringType, Enum: enum}
		}
		if p, ok := zero.(interface{ JSONPattern() string }); ok {
			return &jsonschema.Schema{Type: schemaStringType, Pattern: p.JSONPattern()}
		}
		return nil
	}
	switch t {
	case reflect.TypeOf(Payload{}):
		return &jsonschema.Schema{Type: "object"}
	case reflect.TypeOf(Value{}):
		return &jsonschema.Schema{}
	case reflect.TypeOf(ControlVersions{}):
		return controlVersionsSchema()
	default:
		return nil
	}
}

// controlVersionsSchema returns the version-vector schema of §2.
func controlVersionsSchema() *jsonschema.Schema {
	minLength := uint64(1)
	maxLength := uint64(200)
	maxProperties := uint64(64)
	return &jsonschema.Schema{
		Type:                 "object",
		AdditionalProperties: &jsonschema.Schema{Type: "integer", Minimum: json.Number("0")},
		PropertyNames:        &jsonschema.Schema{MinLength: &minLength, MaxLength: &maxLength},
		MaxProperties:        &maxProperties,
	}
}

// clearDescriptions removes every description so generated output stays
// stable when Go comments change; documentation lives in Go and the spec.
func clearDescriptions(schema *jsonschema.Schema) {
	if schema == nil {
		return
	}
	schema.Description = ""
	if schema.Items != nil {
		clearDescriptions(schema.Items)
	}
	if schema.AdditionalProperties != nil {
		clearDescriptions(schema.AdditionalProperties)
	}
	if schema.PropertyNames != nil {
		clearDescriptions(schema.PropertyNames)
	}
	for _, sub := range schema.AllOf {
		clearDescriptions(sub)
	}
	for _, sub := range schema.AnyOf {
		clearDescriptions(sub)
	}
	for _, sub := range schema.OneOf {
		clearDescriptions(sub)
	}
	if schema.Not != nil {
		clearDescriptions(schema.Not)
	}
	if schema.If != nil {
		clearDescriptions(schema.If)
	}
	if schema.Then != nil {
		clearDescriptions(schema.Then)
	}
	if schema.Else != nil {
		clearDescriptions(schema.Else)
	}
	if schema.Contains != nil {
		clearDescriptions(schema.Contains)
	}
	for _, sub := range schema.Definitions {
		clearDescriptions(sub)
	}
	for _, sub := range schema.PatternProperties {
		clearDescriptions(sub)
	}
	if schema.Properties != nil {
		for pair := schema.Properties.Oldest(); pair != nil; pair = pair.Next() {
			clearDescriptions(pair.Value)
		}
	}
}
